/// <summary>
///     The <c>AVAKBVCreateRequestTable</c> class is the extension for <c>FormRun</c>
/// </summary>
[Form]
public class AVAKBVCreateRequestTable extends FormRun implements IDirPartyQuickCreateCaller
{
    KCS_KBVBuildingProjectID    frmKCS_KBVBuildingProjectID;
    DirPartyRecId               adaDirPartyId1, adaDirPartyId2, adaDirPartyId3;
    ContactPersonId             adaContactPersonId1, adaContactPersonId2, adaContactPersonId3;
    ContactPersonName           contactPersonName;

    KCS_KBVBuildingProjectTable frmKCS_KBVBuildingProjectTable;
    KCS_KBVRequestTable         frmKCS_KBVRequestTable;
    DataAreaId                  frmDataAreaId;

    Name            contactPersonNameCreated;                                 
    boolean         setDirPartyname;                                           
    int             callDirPartyLookupFrom;                                    
    boolean         seekIorName;                                               
    ContactPersonName name1;

}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Args                        locArgs;

    frmDataAreaId           = curExt();

    super();

    if(this.args())
    {
        locArgs = new Args();
        locArgs = this.args();

        if (locArgs.caller())
        {
            if(locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch)
                || locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable))
            {
                KCS_KBVRequestTable.clear();
                if(locArgs.record().TableId == TableNum(KCS_KBVBuildingProjectTable))
                {
                    frmKCS_KBVBuildingProjectTable                  = locArgs.record();
                    frmKCS_KBVBuildingProjectID                     = frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                    KCS_KBVRequestTable.KCS_KBVBuildingProjectID    = frmKCS_KBVBuildingProjectID;
                    KCS_KBVRequestTable.initValue();
                    KCS_KBVRequestTable_DS.object(fieldnum(KCS_KBVRequestTable, KCS_KBVBuildingProjectID)).enabled(false);
                    KCS_KBVRequestTable_DataAreaId.text(frmDataAreaId);
                }
                if(locArgs.record().TableId == TableNum(KCS_KBVRequestTable))
                {
                    frmDataAreaId                                   = locArgs.caller().parmfrmDataAreaId();
                    frmKCS_KBVRequestTable                          = locArgs.record();
                    frmKCS_KBVBuildingProjectTable                  = frmKCS_KBVRequestTable.kcs_KBVBuildingProjectTable();
                    frmKCS_KBVBuildingProjectID                     = frmKCS_KBVRequestTable.KCS_KBVBuildingProjectID;
                    KCS_KBVRequestTable.KCS_KBVBuildingProjectID    = frmKCS_KBVBuildingProjectID;
                    KCS_KBVRequestTable.initValue();
                    KCS_KBVRequestTable_DS.object(fieldnum(KCS_KBVRequestTable, KCS_KBVBuildingProjectID)).enabled(false);
                    KCS_KBVRequestTable_DataAreaId.text(frmDataAreaId);
                }
            }
            if(locArgs.caller().name() == formStr(AVAKBVRequestTable))
            {
                if(locArgs.record().TableId == TableNum(KCS_KBVBuildingProjectTable))
                {
                    frmKCS_KBVBuildingProjectTable                  = locArgs.record();
                }
                if(locArgs.record().TableId == TableNum(KCS_KBVRequestTable))
                {
                    frmKCS_KBVRequestTable                          = locArgs.record();
                    frmKCS_KBVBuildingProjectTable                  = KCS_KBVBuildingProjectTable::find(frmKCS_KBVRequestTable.KCS_KBVBuildingProjectID);
                }

                KCS_KBVRequestTable.clear();
                KCS_KBVRequestTable.initValue();
                KCS_KBVRequestTable_DS.object(fieldnum(KCS_KBVRequestTable, KCS_KBVBuildingProjectID)).enabled(true);
                KCS_KBVRequestTable_KBVBuildingProjectID.text('');
                KCS_KBVRequestTable_DataAreaId.text(curExt());
            }
        }
    }

}

/// <summary>
/// Allows to define defaults on the main data source in the quick create form.
/// </summary>
/// <param name = "_dirPartyEntityDS">Main data source in the quick create form, will be mapped to ContactPerson table.</param>
public void quickCreate_DirPartyEntity_InitValue(FormDataSource _dirPartyEntityDS)
{
    changecompany(frmDataAreaId)
    {
        DirPartyRecId locDirPartyId;

        switch(_dirPartyEntityDS.formRun().args().parmObject().name())
        {
            case ButtonGroupFields1.name():
                locDirPartyId = adaDirPartyId1;
                break;
            case ButtonGroupFields2.name():
                locDirPartyId = adaDirPartyId2;
                break;
            case ButtonGroupFields3.name():
                locDirPartyId = adaDirPartyId3;
                break;
            case ButtonGroupRequester.name():
            default:
                locDirPartyId = KCS_KBVRequestTable.DirPartyId;
                break;
        }

        smmBusRelTable locsmmBusRelTable = smmBusRelTable::findByParty(locDirPartyId);
        ContactPerson _contactPerson = _dirPartyEntityDS.cursor();

        _contactPerson.initFromArgsRecord(locsmmBusRelTable);
    }
}

