/// <summary>
///    AVA <c>checkContactPerson</c> method.
/// </summary>
/// <param name="_dirPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <param name="_contactPersonId">
///    <c>ContactPersonId</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
boolean checkContactPerson( DirPartyRecId   _dirPartyId         = DirPartyId1.value(),
                            ContactPersonId _contactPersonId    = ContactPersonId1.ValueStr())
{
    ContactPerson   locContactPerson;
    CustAccount     locCustAccount;

    locCustAccount  = CustTable::findByPartyRecId(_dirPartyId).AccountNum;

    if (_contactPersonId)
    {
        locContactPerson = ContactPerson::find(_contactPersonId);

        if (!locContactPerson.ContactPersonId)
        {
            return false;
        }
        if (_dirPartyId && locContactPerson.ContactForParty != _dirPartyId)
        {
            return false;
        }
        if (locCustAccount && locContactPerson.getCustAccount() != locCustAccount)
        {
            return false;
        }
    }
    return true;
}

