/// <summary>
///    AVA <c>createIoRs</c> method.
/// </summary>
/// <param name="_kcs_KBVRequestID">
///    <c>KCS_KBVRequestID</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
void createIoRs(KCS_KBVRequestID _kcs_KBVRequestID, KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID)
{
    KCS_KBVInquirerOfTheRequest locKCS_KBVInquirerOfTheRequest;

    changecompany(KCS_KBVRequestTable_DataAreaId.text())
    {
        if (adaDirPartyId1 || adaContactPersonId1)
        {
            locKCS_KBVInquirerOfTheRequest.clear();
            locKCS_KBVInquirerOfTheRequest.initValue();
            locKCS_KBVInquirerOfTheRequest.KCS_KBVBuildingProjectID = _kcs_KBVBuildingProjectID;
            locKCS_KBVInquirerOfTheRequest.KCS_KBVRequestID         = _kcs_KBVRequestID;
            locKCS_KBVInquirerOfTheRequest.DirPartyId               = adaDirPartyId1;
            locKCS_KBVInquirerOfTheRequest.ContactPersonId          = adaContactPersonId1;
            locKCS_KBVInquirerOfTheRequest.insert();

            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(adaDirPartyId1);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVRequestTable.createSmmBusRelTableForCompany(adaDirPartyId1);
            }

        }

        if (adaDirPartyId2 || adaContactPersonId2)
        {
            locKCS_KBVInquirerOfTheRequest.clear();
            locKCS_KBVInquirerOfTheRequest.initValue();
            locKCS_KBVInquirerOfTheRequest.KCS_KBVBuildingProjectID = _kcs_KBVBuildingProjectID;
            locKCS_KBVInquirerOfTheRequest.KCS_KBVRequestID         = _kcs_KBVRequestID;
            locKCS_KBVInquirerOfTheRequest.DirPartyId               = adaDirPartyId2;
            locKCS_KBVInquirerOfTheRequest.ContactPersonId          = adaContactPersonId2;
            locKCS_KBVInquirerOfTheRequest.insert();

            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(adaDirPartyId2);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVRequestTable.createSmmBusRelTableForCompany(adaDirPartyId2);
            }
        }

        if (adaDirPartyId3 || adaContactPersonId3)
        {
            locKCS_KBVInquirerOfTheRequest.clear();
            locKCS_KBVInquirerOfTheRequest.initValue();
            locKCS_KBVInquirerOfTheRequest.KCS_KBVBuildingProjectID = _kcs_KBVBuildingProjectID;
            locKCS_KBVInquirerOfTheRequest.KCS_KBVRequestID         = _kcs_KBVRequestID;
            locKCS_KBVInquirerOfTheRequest.DirPartyId               = adaDirPartyId3;
            locKCS_KBVInquirerOfTheRequest.ContactPersonId          = adaContactPersonId3;
            locKCS_KBVInquirerOfTheRequest.insert();

            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(adaDirPartyId3);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVRequestTable.createSmmBusRelTableForCompany(adaDirPartyId3);
            }
        }
    }
}

/// <summary>
///    AVA <c>contactPersonName</c> method.
/// </summary>
/// <param name="_contactPersonId">
///    <c>ContactPersonId</c> as type
/// </param>
/// <returns>
///     <c>ContactPersonName</c> as type
/// </returns>
ContactPersonName contactPersonName(ContactPersonId _contactPersonId = ContactPersonId1.ValueStr())
{
    if(KCS_KBVRequestTable_DataAreaId.valueStr() != '')
    {
        changecompany(KCS_KBVRequestTable_DataAreaId.valueStr())
        {
            return ContactPerson::name(_contactPersonId);
        }
    }
    else
    {
        return ContactPerson::name(_contactPersonId);
    }
}

