}

/// <summary>
///    AVA <c>closeOk</c> method.
///    last modified: PaffH 06.10.25
/// </summary>
public void closeOk()
{
    Args    locArgs;

    KCS_KBVRequestTable newKCS_KBVRequestTable;
    DataAreaId          localDataArea;
    FormRun             FormRunCaller;

    smmBusRelTable      locSmmBusRelTable;
    boolean             canClose;

    CustTable           locCustTable;

    locArgs         = element.args();
    FormRunCaller   = locArgs.caller();
    canClose        = true;

    changecompany(frmDataAreaId)
    {
        locSmmBusRelTable   = smmBusRelTable::findByParty(KCS_KBVRequestTable.DirPartyId);

        if (locSmmBusRelTable.RecId)
        {
            locCustTable    = CustTable::find(locSmmBusRelTable.custAccount());
        }

        if (    locSmmBusRelTable.RecId
            &&  !locSmmBusRelTable.KCS_RequestEnabled)
        {
            canClose = checkFailed("@NDX:NXARequestIsNotEnabled");
        }

        if (    locCustTable.RecId
            &&  locCustTable.Blocked == CustVendorBlocked::All)
        {
            canClose = checkFailed("@NDX:NXARequesterCustTableBlocked");
        }

        if (KCS_KBVRequestTable.KCS_KBVBuildingProjectID == '')
        {
            canClose = canClose && checkFailed("@NDX:NXABPErrorByRequest");
        }

        if (KCS_KBVRequestTable.DirPartyId == 0)
        {
            canClose = canClose && checkFailed("@NDX:NXARequesterShouldBeFill");
        }

        if (KCS_KBVRequestTable.ContactPersonId == '')
        {
            canClose = canClose && checkFailed("@NDX:NXARequesterContactShouldBeFill");
        }

        if (KCS_KBVBuildingProjectTable::find(KCS_KBVRequestTable.KCS_KBVBuildingProjectID).KCS_KBVStatus == KCS_KBVStatus::Locked)
        {
            canClose = canClose && checkFailed("@NDX:NXABuildingLockNoRequest");
        }

        if (KCS_KBVRequestTable.KCS_KBVDeliveryDate == dateNull())
        {
            canClose = canClose &&  checkFailed("@NDX:NXADeliveryMustBeFilledIn");
        }
    }

    if (!canClose)
    {
        return;
    }

    smmBusRelTable      checkSmmBusRelTable;
    checkSmmBusRelTable = smmBusRelTable::findByParty(KCS_KBVRequestTable.DirPartyId);
    if (!checkSmmBusRelTable.RecId)
    {
        KCS_KBVRequestTable.createSmmBusRelTableForCompany(KCS_KBVRequestTable.DirPartyId);
    }

    super();

    // NDX PaffH 06.10.25 -->
    //if (locArgs.caller())
    //{
    //    if(     locArgs.caller().name() == formStr(AVAKBVRequestTable)
    //        ||  locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable)  
    //        ||  locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch))
    if (this.checkInsertKCS_KBVRequestTable(locArgs))
    // NDX PaffH 06.10.25 <--
    {
        localDataArea   = element.selectedDataAreaId();

        changecompany(localDataArea)
        {
            newKCS_KBVRequestTable.clear();

            Buf2Buf(KCS_KBVRequestTable, newKCS_KBVRequestTable);
            newKCS_KBVRequestTable.KCS_KBVRequestID        = '';
            newKCS_KBVRequestTable.insert();   

            if(newKCS_KBVRequestTable.RecId)
            {
                element.createIoRs(newKCS_KBVRequestTable.KCS_KBVRequestID, newKCS_KBVRequestTable.KCS_KBVBuildingProjectID);

                if(locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable))
                {
                    locArgs.caller().parmCreateRequestOK(true);
                    locArgs.caller().parmKCS_KBVRequestTableCreated(newKCS_KBVRequestTable);
                }
            }
            this.postInsertKCS_KBVRequestTable(newKCS_KBVRequestTable);  // NDX PaffH 06.10.25
        }
    }

    FormDataSource      KCS_KBVRequestTableDS =  FormDataUtil::getFormDataSource(frmKCS_KBVRequestTable);
    if(KCS_KBVRequestTableDS)
    {
        KCS_KBVRequestTableDS.research(true);
    }

    if (formHasMethod(FormRunCaller, literalStr(afterKCS_KBVBuildingProjectCreation)))
    {
        FormRunCaller.afterKCS_KBVBuildingProjectCreation();
    }
    if (formHasMethod(FormRunCaller, literalStr(afterKCS_KBVRequestCreation)))
    {
        FormRunCaller.afterKCS_KBVRequestCreation();
    }

    boolean     BVnewCreated;
    //if (formHasMethod(FormRunCaller, literalStr(parmCreateBPOKAndNewRequest)))
    //{
    //    BVnewCreated = FormRunCaller.parmCreateBPOKAndNewRequest();
    //}

    BVnewCreated = KCS_KBVBuildingProjectTable::numberOfRequestCrossCompany(KCS_KBVRequestTable.KCS_KBVBuildingProjectID,localDataArea) <= 1 ? true : false;


    if (locArgs.caller() && locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable) && BVnewCreated)
    {
        FormTabPageControl  dirGroupTabPage = formRunCaller.design().controlName(formControlStr(AVAKBVBuildingProjectTable,TabPageKCS_DirProductGroup));
        dirGroupTabPage.pageActivated();
    }

    if (locArgs.caller() && locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch))
    {
        Args newargs = new Args();

      //  newargs.record(this.args().record());

        newargs.caller(this);
        newargs.record(KCS_KBVBuildingProjectTable::find(newKCS_KBVRequestTable.KCS_KBVBuildingProjectID));
        newargs.parm('CreateFromSearch');
        new MenuFunction(menuItemDisplayStr(AVAKBVBuildingProjectTable), MenuItemType::Display).run(newArgs);
    }
    if (formHasMethod(FormRunCaller, literalStr(parmCreateBPOKAndNewRequest)))
    {
        FormRunCaller.parmCreateBPOKAndNewRequest(false);
    }

    // NDX PaffH 12.02.24 -->
    if (FormRunCaller is NDXKBVBuildingProjectTableFormRicoKalkI)
    {
        NDXKBVBuildingProjectTableFormRicoKalkI nDXKBVBuildingProjectTableFormRicoKalkI = FormRunCaller as NDXKBVBuildingProjectTableFormRicoKalkI;
        NDXKBVBuildingProject2RicoKalk nDXKBVBuildingProject2RicoKalk = nDXKBVBuildingProjectTableFormRicoKalkI.parmNDXKBVBuildingProject2RicoKalk();
        boolean lDoRicoKalkPublicate;
        [lDoRicoKalkPublicate] = nDXKBVBuildingProject2RicoKalk.doRicoKalkPublicate(KCS_KBVRequestTable.KCS_KBVBuildingProjectID);
        nDXKBVBuildingProject2RicoKalk.parmLRicoRequest(lDoRicoKalkPublicate);
    }
    // NDX PaffH 12.02.24 <--
}

