/// <summary>
///    AVA <c>editContactPersonName_KCS_KBVRequestTable</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_record">
///    <c>KCS_KBVRequestTable</c> as type
/// </param>
/// <param name="_contactPersonId">
///    <c>ContactPersonId</c> as type
/// </param>
/// <returns>
///     <c>ContactPersonName</c> as type
/// </returns>
edit ContactPersonName editContactPersonName_KCS_KBVRequestTable(   boolean             _set,
                                                                    KCS_KBVRequestTable _record,
                                                                    ContactPersonId     _contactPersonId)
{
    ContactPersonName   retVal;

    if (_set)
    {
        AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

        locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

        locAVAKBVDirPartyContactPersonHelper.parmSet(_set);
        locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(frmDataAreaId);
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(_record.DirPartyId);

        locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(_contactPersonId);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(_contactPersonId);

        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonName();
      // retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonNameModified();

        _record.DirPartyId      = locAVAKBVDirPartyContactPersonHelper.parmDirPartyId();
        _record.ContactPersonId = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();


    }
    else
    {
        changecompany(frmDataAreaId)
        {
            retVal = ContactPerson::find(_record.ContactPersonId).personName();
        }
    }

    return retVal;

}

