/// <summary>
///    AVA <c>lookup</c> method.
/// </summary>
void lookup()
{
    Args            locArgsService;
    smmBusRelTable  locsmmBusRelTable;

    changecompany(frmDataAreaId)
    {
        locArgsService = new Args();

        if (KCS_KBVRequestTable.DirPartyId)
        {
            locsmmBusRelTable = smmBusRelTable::findByParty(KCS_KBVRequestTable.DirPartyId);
            // adHoc generation of missing contacts
            if(locsmmBusRelTable.RecId)
            {
                locArgsService.record(locsmmBusRelTable);
                locArgsService.caller(this.formRun());
                locArgsService.parmObject(this);
                locArgsService.menuItemType(MenuItemType::Action);
                locArgsService.menuItemName(menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel));
                AVACreateContactPersonBasedOnGABController::main(locArgsService);
            }
        }

        ContactPerson::lookupDirContactPerson(  KCS_KBVRequestTable_ContactPersonId,
                                                KCS_KBVRequestTable_DirPartyId.value(),
                                                this,
                                                KCS_KBVRequestTable_ContactPersonId.valueStr());
    }
}

